def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    for c in range(w):
        if grid[h-1][c] == 5:
            color=next((grid[r][c] for r in range(h-2,-1,-1) if grid[r][c] != 0), 5)
            for r in range(h-1):
                if out[r][c] == 0:
                    out[r][c]=color
    return out
